const payload = $json.body || $json;
const event = payload.event || payload;
const resource = event.resource || {};

const chatId = String(resource.chat_id || '');
const messageId = String(resource.message_id || '');
const text = String(resource.text || '');
const fileKeys = Array.isArray(resource.file_keys)
  ? resource.file_keys.map((k) => String(k || '').trim()).filter(Boolean)
  : [];
const fileKey = String(resource.file_key || fileKeys[0] || '').trim();

const okText = text.includes('发票号校验');
const hasFile = Boolean(fileKey);

let failReason = '';
if (!okText) failReason = '文案未包含「发票号校验」';
else if (!messageId) failReason = '缺少 message_id';
else if (!hasFile) failReason = '未找到 Excel 附件（file_key）';

return [
  {
    json: {
      chat_id: chatId,
      message_id: messageId,
      text,
      file_key: fileKey,
      file_keys: fileKeys.length ? fileKeys : fileKey ? [fileKey] : [],
      ready: !failReason,
      fail_reason: failReason,
    },
  },
];

