const rows = $input.all().map((i) => i.json);

function cell(row, ...keys) {
  for (const key of keys) {
    if (row[key] != null && String(row[key]).trim() !== '') {
      return String(row[key]).trim();
    }
  }
  // fuzzy: header may have spaces
  for (const [k, v] of Object.entries(row || {})) {
    const nk = String(k).replace(/\s+/g, '');
    if (keys.some((want) => nk === String(want).replace(/\s+/g, ''))) {
      if (v != null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
}

const taxMap = {};
for (const row of rows) {
  const no = cell(row, '数电发票号码');
  if (!no) continue;
  taxMap[no] = {
    status: cell(row, '发票状态') || '',
    risk: cell(row, '发票风险等级') || '',
  };
}

const ctx = $('解析事件').first().json;
const chatToken = $('获取ChatToken').first().json.tenant_access_token;

if (!Object.keys(taxMap).length) {
  return [
    {
      json: {
        ok: false,
        fail_reason: 'Excel「发票基础信息」中没有有效的数电发票号码',
        chat_id: ctx.chat_id,
        message_id: ctx.message_id,
        chat_token: chatToken,
        taxMap: {},
        taxCount: 0,
      },
    },
  ];
}

return [
  {
    json: {
      ok: true,
      chat_id: ctx.chat_id,
      message_id: ctx.message_id,
      chat_token: chatToken,
      taxMap,
      taxCount: Object.keys(taxMap).length,
    },
  },
];

const prev = $('构建taxMap').first().json;
const taxMap = prev.taxMap || {};
const mainToken = $json.tenant_access_token;
const baseId = $env.FEISHU_BASE_ID;
const tableId = 'tblNd9zgN7ALihwj';

if (!baseId) {
  throw new Error('缺少环境变量 FEISHU_BASE_ID');
}

async function feishuPost(url, body) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      Authorization: `Bearer ${mainToken}`,
      'Content-Type': 'application/json',
    },
    body,
    json: true,
  });
  return resp;
}

const records = [];
let pageToken = '';
for (let page = 0; page < 50; page++) {
  const qs = new URLSearchParams({ page_size: '500' });
  if (pageToken) qs.set('page_token', pageToken);
  const url = `https://open.feishu.cn/open-apis/bitable/v1/apps/${baseId}/tables/${tableId}/records/search?${qs}`;
  const resp = await feishuPost.call(this, url, {
    field_names: ['发票号码'],
  });
  if (resp.code !== 0) {
    throw new Error(`拉取回票表失败: ${resp.msg || JSON.stringify(resp)}`);
  }
  const data = resp.data || {};
  records.push(...(data.items || []));
  if (!data.has_more) break;
  pageToken = data.page_token || '';
  if (!pageToken) break;
}

function splitInvoiceNos(raw) {
  if (raw == null) return [];
  return String(raw)
    .split(/[，,;；\s]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function fieldText(fields, name) {
  const v = fields?.[name];
  if (v == null) return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v);
  if (Array.isArray(v)) {
    return v
      .map((x) => {
        if (x == null) return '';
        if (typeof x === 'string' || typeof x === 'number') return String(x);
        if (typeof x === 'object') return String(x.text || x.name || x.value || '');
        return '';
      })
      .filter(Boolean)
      .join('，');
  }
  if (typeof v === 'object') return String(v.text || v.name || v.value || '');
  return String(v);
}

const bitableMap = {};
for (const rec of records) {
  const recordId = rec.record_id || rec.id;
  if (!recordId) continue;
  const nos = splitInvoiceNos(fieldText(rec.fields || {}, '发票号码'));
  for (const no of nos) {
    bitableMap[no] = recordId;
  }
}

const problemsByRecord = {};
for (const [no, recordId] of Object.entries(bitableMap)) {
  const tax = taxMap[no];
  if (!tax) {
    if (!problemsByRecord[recordId]) problemsByRecord[recordId] = [];
    problemsByRecord[recordId].push(`未找到:${no}`);
    continue;
  }
  if (tax.status !== '正常' || tax.risk !== '正常') {
    if (!problemsByRecord[recordId]) problemsByRecord[recordId] = [];
    problemsByRecord[recordId].push(
      `状态异常(${tax.status || '-'}/${tax.risk || '-'}):${no}`,
    );
  }
}

const updates = Object.entries(problemsByRecord).map(([record_id, parts]) => ({
  record_id,
  fields: {
    税务系统状态: parts.join('；'),
  },
}));

const problemCount = updates.length;
let updateFailed = 0;

for (let i = 0; i < updates.length; i += 500) {
  const chunk = updates.slice(i, i + 500);
  const url = `https://open.feishu.cn/open-apis/bitable/v1/apps/${baseId}/tables/${tableId}/records/batch_update`;
  const resp = await feishuPost.call(this, url, { records: chunk });
  if (resp.code !== 0) {
    updateFailed += chunk.length;
  }
}

const replyText =
  updateFailed > 0
    ? `校验完成：${problemCount} 条有问题（其中 ${updateFailed} 条回写失败）`
    : `校验完成：${problemCount} 条有问题`;

return [
  {
    json: {
      ok: true,
      problemCount,
      updateFailed,
      taxCount: prev.taxCount,
      bitableInvoiceCount: Object.keys(bitableMap).length,
      bitableRecordCount: records.length,
      chat_id: prev.chat_id,
      message_id: prev.message_id,
      chat_token: prev.chat_token,
      reply_text: replyText,
      sample_updates: updates.slice(0, 5),
    },
  },
];
